// Frozen known-good SHA-256 of each trusted method's canonical, type-tagged
// code encoding (CPython 3.11 / pandas 2.3.3 / numpy 2.3.5). Immutable
// constants, never regenerated from a live descriptor.
const __RXTPD_SERIES_MAP_DIGEST: &str = "4f755e3868aee6be8e0d29b39354354d8829da3c0a00c4c1bc48dab3e83f9c4d";
const __RXTPD_SERIES_TO_NUMPY_DIGEST: &str = "1d2a907fafe5072adc69dde5099e4a83b48102e68e9d35e0aafbec8d16e70050";
const __RXTPD_FRAME_APPLY_DIGEST: &str = "82441419a1a610c5b2e81af0c6978974682fb3116e8f10de5b9313641fec00d1";
const __RXTPD_FRAME_TO_NUMPY_DIGEST: &str = "ff8ef88dbed7a3c530f339452059b2aae33e65e73c3f58ae60f01c4469bb5e71";
const __RXTPD_APPLY_FRAME_APPLY_DIGEST: &str = "38fa716dab42aa69bddb5dfc11c58f9b7c5b64e8e2f97dd2a5f5630cbfb168c2";
// The three ``pandas.core.apply`` members ``frame_apply`` loads are validated
// against these independently frozen authorities -- a function code digest and
// two structural class digests -- never by self-comparison to the same module.
const __RXTPD_RECONSTRUCT_FUNC_DIGEST: &str = "08c2f2b0acd3ae10826d7ef7cb654735fd8ace9ed4d9d09b78cf45e014eba27a";
const __RXTPD_FRAME_COLUMN_APPLY_CLASS_DIGEST: &str = "e95b5a9a8d4beeabdcc25d3240bc73b49d2d420b90ac9522fc75655764782f7f";
