fn __rxtpd_type_error(message: &'static str) -> pyo3::PyErr {
    pyo3::exceptions::PyTypeError::new_err(message)
}

fn __rxtpd_push_str(buffer: &mut Vec<u8>, text: &str) {
    let bytes = text.as_bytes();
    buffer.push(b's');
    buffer.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
    buffer.extend_from_slice(bytes);
}

fn __rxtpd_encode_value(
    value: &pyo3::Bound<'_, pyo3::PyAny>,
    buffer: &mut Vec<u8>,
    error: &'static str,
) -> pyo3::PyResult<()> {
    use pyo3::types::{PyAnyMethods, PyBool, PyInt, PyString, PyTuple, PyTupleMethods};
    // Accept only the exact builtin constant types present in the pinned code
    // objects; reject any custom/unknown object before it can reach the hash.
    if value.is_none() {
        buffer.push(b'N');
        return Ok(());
    }
    if value.is_exact_instance_of::<PyBool>() {
        let flag: bool = value.extract().map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(if flag { b'T' } else { b'F' });
        return Ok(());
    }
    if value.is_exact_instance_of::<PyInt>() {
        let number: i64 = value.extract().map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(b'i');
        buffer.extend_from_slice(&number.to_le_bytes());
        return Ok(());
    }
    if value.is_exact_instance_of::<PyString>() {
        let text: String = value.extract().map_err(|_| __rxtpd_type_error(error))?;
        let bytes = text.as_bytes();
        buffer.push(b's');
        buffer.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
        buffer.extend_from_slice(bytes);
        return Ok(());
    }
    if value.is_exact_instance_of::<PyTuple>() {
        let tuple = value
            .cast::<PyTuple>()
            .map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(b't');
        buffer.extend_from_slice(&(tuple.len() as u32).to_le_bytes());
        for item in tuple.iter() {
            __rxtpd_encode_value(&item, buffer, error)?;
        }
        return Ok(());
    }
    // Nested code objects (comprehensions / nested defs stored as consts) are
    // folded in recursively so behavior cannot hide inside them.
    let code_type = value.py().import("types")?.getattr("CodeType")?;
    if value.is_exact_instance(&code_type) {
        buffer.push(b'c');
        __rxtpd_encode_code(value, buffer, error)?;
        return Ok(());
    }
    Err(__rxtpd_type_error(error))
}

fn __rxtpd_encode_code(
    code: &pyo3::Bound<'_, pyo3::PyAny>,
    buffer: &mut Vec<u8>,
    error: &'static str,
) -> pyo3::PyResult<()> {
    use pyo3::types::{PyAnyMethods, PyString, PyTuple, PyTupleMethods};
    for name in [
        "co_argcount",
        "co_posonlyargcount",
        "co_kwonlyargcount",
        "co_nlocals",
        "co_flags",
        "co_stacksize",
    ] {
        let value: i64 = code
            .getattr(name)?
            .extract()
            .map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(b'i');
        buffer.extend_from_slice(&value.to_le_bytes());
    }
    for name in ["co_code", "co_exceptiontable"] {
        let raw: Vec<u8> = code
            .getattr(name)?
            .extract()
            .map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(b'b');
        buffer.extend_from_slice(&(raw.len() as u32).to_le_bytes());
        buffer.extend_from_slice(&raw);
    }
    for name in ["co_names", "co_varnames", "co_freevars", "co_cellvars"] {
        let field = code.getattr(name)?;
        let tuple = field
            .cast::<PyTuple>()
            .map_err(|_| __rxtpd_type_error(error))?;
        buffer.push(b't');
        buffer.extend_from_slice(&(tuple.len() as u32).to_le_bytes());
        for item in tuple.iter() {
            if !item.is_exact_instance_of::<PyString>() {
                return Err(__rxtpd_type_error(error));
            }
            let text: String = item.extract().map_err(|_| __rxtpd_type_error(error))?;
            let bytes = text.as_bytes();
            buffer.push(b's');
            buffer.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
            buffer.extend_from_slice(bytes);
        }
    }
    for name in ["co_name", "co_qualname"] {
        let text: String = code
            .getattr(name)?
            .extract()
            .map_err(|_| __rxtpd_type_error(error))?;
        let bytes = text.as_bytes();
        buffer.push(b's');
        buffer.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
        buffer.extend_from_slice(bytes);
    }
    let consts_field = code.getattr("co_consts")?;
    let consts = consts_field
        .cast::<PyTuple>()
        .map_err(|_| __rxtpd_type_error(error))?;
    buffer.push(b't');
    buffer.extend_from_slice(&(consts.len() as u32).to_le_bytes());
    for item in consts.iter() {
        __rxtpd_encode_value(&item, buffer, error)?;
    }
    Ok(())
}

fn __rxtpd_sha256_hex(buffer: &[u8]) -> String {
    use sha2::Digest;
    let mut hasher = sha2::Sha256::new();
    hasher.update(buffer);
    let digest = hasher.finalize();
    let mut hex = String::with_capacity(64);
    for byte in digest.iter() {
        hex.push_str(&format!("{:02x}", byte));
    }
    hex
}

fn __rxtpd_code_digest(
    code: &pyo3::Bound<'_, pyo3::PyAny>,
    error: &'static str,
) -> pyo3::PyResult<String> {
    let mut buffer: Vec<u8> = Vec::new();
    __rxtpd_encode_code(code, &mut buffer, error)?;
    Ok(__rxtpd_sha256_hex(&buffer))
}

fn __rxtpd_validate_series_map(
    py: pyo3::Python<'_>,
    descriptor: &pyo3::Bound<'_, pyo3::PyAny>,
) -> pyo3::PyResult<()> {
    use pyo3::types::{PyAnyMethods, PyTuple, PyTupleMethods};
    let error = "rextio-pandas Series contract requires the pinned pandas.Series.map descriptor with no instance override";
    let types_module = py.import("types")?;
    if !descriptor.is_exact_instance(&types_module.getattr("FunctionType")?) {
        return Err(__rxtpd_type_error(error));
    }
    let module = py.import("pandas.core.series")?;
    if descriptor.getattr("__module__")?.extract::<String>()? != "pandas.core.series" {
        return Err(__rxtpd_type_error(error));
    }
    if descriptor.getattr("__qualname__")?.extract::<String>()? != "Series.map" {
        return Err(__rxtpd_type_error(error));
    }
    let module_dict = module.getattr("__dict__")?;
    if !descriptor.getattr("__globals__")?.is(&module_dict) {
        return Err(__rxtpd_type_error(error));
    }
    if !descriptor.getattr("__closure__")?.is_none() {
        return Err(__rxtpd_type_error(error));
    }
    let code = descriptor.getattr("__code__")?;
    if code.getattr("co_freevars")?.len()? != 0 {
        return Err(__rxtpd_type_error(error));
    }
    if __rxtpd_code_digest(&code, error)? != __RXTPD_SERIES_MAP_DIGEST {
        return Err(__rxtpd_type_error(error));
    }
    if !descriptor.getattr("__kwdefaults__")?.is_none() {
        return Err(__rxtpd_type_error(error));
    }
    let defaults = descriptor.getattr("__defaults__")?;
    if !defaults.is_exact_instance_of::<PyTuple>() {
        return Err(__rxtpd_type_error(error));
    }
    let defaults = defaults.cast::<PyTuple>().map_err(|_| __rxtpd_type_error(error))?;
    if defaults.len() != 1 {
        return Err(__rxtpd_type_error(error));
    }
    {
        let item = defaults.get_item(0)?;
        if !item.is_none() {
            return Err(__rxtpd_type_error(error));
        }
    }
    Ok(())
}

